## Deploying sql with sql user
* Make pasword file in user dir C:\Users\<user>\.devops\operator-<user>.txt
* Modify deploy_sql.bat file

```bat
@echo off
set "un=%USERNAME%"
set "filename=C:\Users\%un%\.devops\operator-%un%.txt"
SETLOCAL ENABLEDELAYEDEXPANSION
IF EXIST %filename% (
    set /p pw=<%filename%
    echo sqlcmd -b -S%1 -vCUSTOMERNAME=%2 -vAREANAME=%3 -vUSERNAME=%5 -vDistPath="..\.." -i"..\sql\00_MasterScript.sql" -U %un% -P xxx
    sqlcmd -b -S%1 -vCUSTOMERNAME=%2 -vAREANAME=%3 -vUSERNAME=%5 -vDistPath="..\.." -i"..\sql\00_MasterScript.sql" -U %un% -P !pw!
) ELSE (
    echo sqlcmd -b -S%1 -vCUSTOMERNAME=%2 -vAREANAME=%3 -vUSERNAME=%5 -vDistPath="..\.." -i"..\sql\00_MasterScript.sql"
    sqlcmd -b -S%1 -vCUSTOMERNAME=%2 -vAREANAME=%3 -vUSERNAME=%5 -vDistPath="..\.." -i"..\sql\00_MasterScript.sql"
)

```

